import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { 
  MessageCircle, X, Paperclip, Smile, Mic, 
  Send, Clock, Check, CheckCheck,
  User, Users, Info, AlertCircle
} from 'lucide-react';
import { io } from 'socket.io-client';

const ChatModal = ({ currentUser, isAuthenticated, onClose }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [conversation, setConversation] = useState(null);
  const [adminInfo, setAdminInfo] = useState(null);
  const [socket, setSocket] = useState(null);
  const [error, setError] = useState(null);
  const [typingTimeout, setTypingTimeout] = useState(null);
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);

  // URL de base pour les APIs
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';
  const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';

  // Récupérer le token
  const getAuthToken = () => {
    const token = localStorage.getItem('authToken');
    return token;
  };

  // Vérifier l'authentification au chargement
  useEffect(() => {
    if (!isAuthenticated || !currentUser) {
      setError('Vous devez être connecté pour utiliser le chat');
      setIsLoading(false);
    }
  }, [isAuthenticated, currentUser]);

  // Initialiser Socket.io
  useEffect(() => {
    if (isAuthenticated && currentUser && getAuthToken()) {
      try {
        const newSocket = io(SOCKET_URL, {
          auth: {
            token: getAuthToken()
          },
          transports: ['websocket', 'polling'],
          reconnection: true,
          reconnectionAttempts: 5,
          reconnectionDelay: 1000,
          timeout: 10000
        });

        newSocket.on('connect', () => {
          console.log('✅ Connecté au serveur de chat');
          setError(null);

          // Rejoindre la conversation si elle existe
          if (conversation?.id) {
            newSocket.emit('joinConversation', conversation.id);
          }
        });

        newSocket.on('connect_error', (err) => {
          console.error('❌ Erreur de connexion Socket.io:', err.message);
          setError('Connexion au chat temporairement indisponible');
        });

        newSocket.on('new_message', (message) => {
          console.log('Nouveau message reçu:', message);
          handleNewMessage(message);
        });

        newSocket.on('typing_start', (data) => {
          if (data.conversationId === conversation?.id && data.userId !== currentUser.id) {
            setIsTyping(true);
          }
        });

        newSocket.on('typing_stop', (data) => {
          if (data.conversationId === conversation?.id && data.userId !== currentUser.id) {
            setIsTyping(false);
          }
        });

        newSocket.on('message_read', (data) => {
          updateMessageStatus(data.messageIds, 'read');
        });

        newSocket.on('conversation_updated', (updatedConversation) => {
          if (updatedConversation.id === conversation?.id) {
            setConversation(updatedConversation);
          }
        });

        newSocket.on('user_connected', (userId) => {
          console.log(`Utilisateur ${userId} connecté`);
        });

        newSocket.on('user_disconnected', (userId) => {
          console.log(`Utilisateur ${userId} déconnecté`);
        });

        setSocket(newSocket);

        return () => {
          if (newSocket) {
            newSocket.disconnect();
          }
          if (typingTimeout) {
            clearTimeout(typingTimeout);
          }
        };
      } catch (socketError) {
        console.error('Erreur d\'initialisation Socket.io:', socketError);
        setError('Impossible de se connecter au chat en temps réel');
      }
    }
  }, [isAuthenticated, currentUser, conversation]);

  // Charger la conversation
  useEffect(() => {
    if (isAuthenticated && currentUser && getAuthToken()) {
      loadOrCreateConversation();
    }
  }, [isAuthenticated, currentUser]);

  const loadOrCreateConversation = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const token = getAuthToken();

      if (!token) {
        setError('Session expirée. Veuillez vous reconnecter.');
        navigate('/login');
        return;
      }

      // Configuration des headers axios
      const config = {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        timeout: 10000
      };

      // 1. Vérifier si l'utilisateur a déjà une conversation active
      const response = await axios.get(`${API_URL}/messages/conversations/my-conversations`, config);

      let conversationData = null;

      if (response.data.success && response.data.conversations.length > 0) {
        // Chercher une conversation ouverte
        conversationData = response.data.conversations.find(c => 
          c.status === 'open' || c.status === 'pending'
        );

        // Sinon, prendre la dernière conversation
        if (!conversationData) {
          conversationData = response.data.conversations[0];
        }
      }

      // 2. Si pas de conversation, créer une nouvelle conversation
      if (!conversationData) {
        console.log('Création d\'une nouvelle conversation...');

        // Récupérer un admin disponible
        let adminId = null;
        try {
          const adminsResponse = await axios.get(`${API_URL}/users/admins/available`, config);

          if (adminsResponse.data.success && adminsResponse.data.admins.length > 0) {
            // Prendre le premier admin disponible
            adminId = adminsResponse.data.admins[0].id;
          } else {
            // Assigner à un admin par défaut
            const defaultAdmins = await axios.get(`${API_URL}/users/admins`, config);
            if (defaultAdmins.data.success && defaultAdmins.data.admins.length > 0) {
              adminId = defaultAdmins.data.admins[0].id;
            }
          }
        } catch (adminError) {
          console.error('Erreur lors de la recherche d\'un admin:', adminError);
          // Fallback: utiliser l'admin ID 1
          adminId = 1;
        }

        if (!adminId) {
          throw new Error('Aucun administrateur disponible');
        }

        // Créer la conversation
        const newConvResponse = await axios.post(
          `${API_URL}/messages/conversations`, 
          { 
            title: `Support - ${currentUser.first_name} ${currentUser.last_name}`,
            admin_id: adminId 
          },
          config
        );

        if (newConvResponse.data.success) {
          conversationData = newConvResponse.data.conversation;
          console.log('Nouvelle conversation créée:', conversationData);
        } else {
          throw new Error('Échec de la création de la conversation');
        }
      }

      // 3. Charger les informations de l'admin
      if (conversationData && conversationData.admin_id) {
        await loadAdminInfo(conversationData.admin_id);
      }

      // 4. Charger les messages de la conversation
      if (conversationData) {
        setConversation(conversationData);
        await loadMessages(conversationData.id);
      }

      // 5. Joindre la conversation via socket
      if (socket && socket.connected && conversationData) {
        socket.emit('joinConversation', conversationData.id);
      }

    } catch (error) {
      console.error('Erreur lors du chargement de la conversation:', error);
      setError(error.response?.data?.message || 'Impossible de charger le chat. Veuillez réessayer.');
      setIsLoading(false);
    }
  };

  const loadAdminInfo = async (adminId) => {
    try {
      const token = getAuthToken();
      const config = {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      };

      const response = await axios.get(`${API_URL}/users/${adminId}`, config);

      if (response.data.success) {
        setAdminInfo(response.data.user);
      } else {
        // Info admin par défaut
        setAdminInfo({
          id: adminId,
          first_name: 'Conseiller',
          last_name: 'Nexus',
          role: 'admin',
          status: 'online'
        });
      }
    } catch (error) {
      console.error('Erreur chargement info admin:', error);
      setAdminInfo({
        id: adminId,
        first_name: 'Conseiller',
        last_name: 'Nexus',
        role: 'admin',
        status: 'offline'
      });
    }
  };

  const loadMessages = async (conversationId) => {
    try {
      const token = getAuthToken();
      const response = await axios.get(
        `${API_URL}/messages/conversations/${conversationId}/messages`, 
        {
          headers: { 
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          },
          params: {
            limit: 50,
            offset: 0
          }
        }
      );

      if (response.data.success) {
        const messagesWithSenders = await Promise.all(
          (response.data.messages || []).map(async (message) => {
            try {
              // Pour chaque message, récupérer les infos de l'expéditeur
              const senderResponse = await axios.get(
                `${API_URL}/users/${message.sender_id}`,
                {
                  headers: { 
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                  }
                }
              );

              return {
                ...message,
                sender: senderResponse.data.success ? senderResponse.data.user : {
                  id: message.sender_id,
                  first_name: 'Utilisateur',
                  last_name: ''
                }
              };
            } catch (error) {
              return {
                ...message,
                sender: {
                  id: message.sender_id,
                  first_name: message.sender_id === currentUser.id ? currentUser.first_name : 'Conseiller',
                  last_name: message.sender_id === currentUser.id ? currentUser.last_name : 'Nexus'
                }
              };
            }
          })
        );

        setMessages(messagesWithSenders);

        // Marquer les messages comme lus
        const unreadMessages = messagesWithSenders
          .filter(msg => !msg.is_read && msg.sender_id !== currentUser.id)
          .map(msg => msg.id);

        if (unreadMessages.length > 0) {
          markMessagesAsRead(unreadMessages);
        }
      }
    } catch (error) {
      console.error('Erreur lors du chargement des messages:', error);
      setError('Impossible de charger les messages');
      setMessages([]);
    } finally {
      setIsLoading(false);
    }
  };

  const markMessagesAsRead = async (messageIds) => {
    try {
      const token = getAuthToken();
      await axios.post(
        `${API_URL}/messages/mark-read`,
        { messageIds },
        {
          headers: { 
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        }
      );

      // Émettre via socket
      if (socket && socket.connected && conversation) {
        socket.emit('mark_read', {
          conversationId: conversation.id,
          messageIds
        });
      }
    } catch (error) {
      console.error('Erreur lors du marquage des messages comme lus:', error);
    }
  };

  const handleNewMessage = (message) => {
    setMessages(prev => [...prev, message]);

    // Si le message est de l'autre utilisateur, le marquer comme lu
    if (message.sender_id !== currentUser.id) {
      markMessagesAsRead([message.id]);
    }

    scrollToBottom();
  };

  const updateMessageStatus = (messageIds, status) => {
    setMessages(prev => prev.map(msg => 
      messageIds.includes(msg.id) 
        ? { ...msg, status, is_read: status === 'read' }
        : msg
    ));
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || !conversation || !currentUser) return;

    const messageData = {
      content: inputMessage.trim(),
      conversation_id: conversation.id
    };

    try {
      const token = getAuthToken();
      if (!token) {
        setError('Session expirée. Veuillez vous reconnecter.');
        navigate('/login');
        return;
      }

      // Message temporaire pour UX
      const tempMessage = {
        id: `temp_${Date.now()}`,
        ...messageData,
        sender_id: currentUser.id,
        created_at: new Date().toISOString(),
        is_read: false,
        status: 'sending',
        sender: {
          id: currentUser.id,
          first_name: currentUser.first_name,
          last_name: currentUser.last_name,
          avatar: currentUser.avatar
        }
      };

      // Ajouter le message localement immédiatement
      setMessages(prev => [...prev, tempMessage]);
      setInputMessage('');
      scrollToBottom();

      // Arrêter l'indicateur de frappe
      if (socket && socket.connected) {
        socket.emit('typing_stop', {
          conversationId: conversation.id,
          userId: currentUser.id
        });
      }

      // Envoyer via API
      const response = await axios.post(
        `${API_URL}/messages`, 
        messageData,
        { 
          headers: { 
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        }
      );

      if (response.data.success) {
        const newMessage = {
          ...response.data.message,
          sender: {
            id: currentUser.id,
            first_name: currentUser.first_name,
            last_name: currentUser.last_name,
            avatar: currentUser.avatar
          }
        };

        // Remplacer le message temporaire par le vrai message
        setMessages(prev => prev.map(msg => 
          msg.id === tempMessage.id ? newMessage : msg
        ));

        // Émettre via socket
        if (socket && socket.connected) {
          socket.emit('new_message', {
            conversationId: conversation.id,
            message: newMessage
          });
        }

      } else {
        throw new Error('Échec de l\'envoi du message');
      }

    } catch (error) {
      console.error('Erreur lors de l\'envoi du message:', error);

      // Marquer le message temporaire comme erreur
      setMessages(prev => prev.map(msg => 
        msg.id?.startsWith('temp_') 
          ? { ...msg, status: 'error', error: true }
          : msg
      ));

      setError(error.response?.data?.message || 'Impossible d\'envoyer le message. Réessayez.');
    }
  };

  const handleTyping = () => {
    if (socket && socket.connected && conversation) {
      // Émettre l'événement de frappe
      socket.emit('typing_start', {
        conversationId: conversation.id,
        userId: currentUser.id
      });

      // Annuler le timeout précédent
      if (typingTimeout) {
        clearTimeout(typingTimeout);
      }

      // Définir un nouveau timeout pour arrêter l'indicateur de frappe
      const timeout = setTimeout(() => {
        socket.emit('typing_stop', {
          conversationId: conversation.id,
          userId: currentUser.id
        });
      }, 3000);

      setTypingTimeout(timeout);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const scrollToBottom = () => {
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, 100);
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Formatage de l'heure
  const formatTime = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    } catch {
      return '--:--';
    }
  };

  // Formatage de la date pour les séparateurs
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    if (date.toDateString() === today.toDateString()) {
      return 'Aujourd\'hui';
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Hier';
    } else {
      return date.toLocaleDateString('fr-FR', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
    }
  };

  // Regrouper les messages par date
  const groupMessagesByDate = () => {
    const groups = {};
    messages.forEach(message => {
      const date = new Date(message.created_at).toDateString();
      if (!groups[date]) {
        groups[date] = [];
      }
      groups[date].push(message);
    });
    return groups;
  };

  // Fonction pour recharger la conversation
  const handleRetry = () => {
    setError(null);
    setIsLoading(true);
    loadOrCreateConversation();
  };

  if (!isAuthenticated || !currentUser) {
    return (
      <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50 animate-slide-up">
        <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-t-2xl">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
                <MessageCircle className="h-5 w-5" />
              </div>
              <div>
                <h3 className="font-bold">Support Nexus</h3>
                <p className="text-xs opacity-90">Connectez-vous pour chatter</p>
              </div>
            </div>
            <button 
              onClick={onClose} 
              className="p-2 hover:bg-white/20 rounded-lg transition-colors"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
        <div className="p-6 text-center">
          <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-300 mb-4">
            Connectez-vous pour discuter avec notre équipe de support
          </p>
          <button
            onClick={() => navigate('/login')}
            className="w-full py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:opacity-90 transition-opacity mb-3"
          >
            Se connecter
          </button>
          <button
            onClick={onClose}
            className="w-full py-3 border border-neutral-300 dark:border-neutral-700 rounded-xl font-medium hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
          >
            Fermer
          </button>
        </div>
      </div>
    );
  }

  const messageGroups = groupMessagesByDate();

  return (
    <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50 animate-slide-up">
      {/* Header avec infos admin */}
      <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-t-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            {adminInfo?.avatar ? (
              <img 
                src={adminInfo.avatar} 
                alt={adminInfo.first_name}
                className="h-10 w-10 rounded-full border-2 border-white/30 object-cover"
              />
            ) : (
              <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
                <User className="h-5 w-5" />
              </div>
            )}
            <div>
              <h3 className="font-bold">
                {adminInfo ? `${adminInfo.first_name} ${adminInfo.last_name}` : 'Support Nexus'}
              </h3>
              <p className="text-xs opacity-90">
                {adminInfo?.role === 'admin' ? 'Conseiller • ' : ''}
                {adminInfo?.status === 'online' ? 'En ligne' : 'Hors ligne'}
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-2">
            <button 
              onClick={onClose} 
              className="p-2 hover:bg-white/20 rounded-lg transition-colors"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Statut de la conversation */}
        <div className="mt-2 flex items-center justify-between text-xs">
          <span className="bg-white/20 px-2 py-1 rounded">
            {conversation?.title || `Ticket #${conversation?.id?.toString().substring(0, 8) || 'NEW'}`}
          </span>
          <div className="flex items-center">
            <div className={`h-2 w-2 rounded-full mr-1 ${conversation?.status === 'open' ? 'bg-green-400 animate-pulse' : 'bg-yellow-400'}`}></div>
            <span>{conversation?.status === 'open' ? 'Ouvert' : 'En attente'}</span>
          </div>
        </div>
      </div>

      {/* Zone des messages */}
      <div className="h-64 sm:h-72 p-4 overflow-y-auto bg-gray-50 dark:bg-neutral-950">
        {error && !isLoading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-3">
            <AlertCircle className="h-12 w-12 text-red-500" />
            <p className="text-center text-red-600 dark:text-red-400">{error}</p>
            <button
              onClick={handleRetry}
              className="px-4 py-2 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors"
            >
              Réessayer
            </button>
          </div>
        ) : isLoading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-4">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
            <p className="text-gray-600 dark:text-gray-400">Chargement des messages...</p>
          </div>
        ) : (
          <div className="space-y-4">
            {messages.length === 0 ? (
              <div className="text-center py-8">
                <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-3" />
                <p className="text-gray-600 dark:text-gray-400">
                  Aucun message. Commencez la conversation !
                </p>
              </div>
            ) : (
              Object.entries(messageGroups).map(([date, dateMessages]) => (
                <div key={date}>
                  {/* Séparateur de date */}
                  <div className="flex items-center justify-center my-4">
                    <div className="text-xs text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-neutral-800 px-3 py-1 rounded-full">
                      {formatDate(dateMessages[0].created_at)}
                    </div>
                  </div>

                  {/* Messages de cette date */}
                  {dateMessages.map((message) => (
                    <div
                      key={message.id}
                      className={`flex ${message.sender_id === currentUser.id ? 'justify-end' : 'justify-start'} mb-3`}
                    >
                      <div className={`max-w-[85%] rounded-2xl p-3 ${
                        message.sender_id === currentUser.id
                          ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                          : 'bg-white dark:bg-neutral-800 text-gray-900 dark:text-white rounded-bl-none border border-neutral-200 dark:border-neutral-700'
                      } ${message.error ? 'border-red-300 dark:border-red-800 opacity-70' : ''} 
                      ${message.status === 'sending' ? 'opacity-70' : ''}`}>

                        {message.sender_id !== currentUser.id && (
                          <div className="flex items-center space-x-2 mb-1">
                            <span className="text-xs font-medium text-primary-600 dark:text-primary-400">
                              {message.sender?.first_name || 'Conseiller'}
                            </span>
                          </div>
                        )}

                        <p className="text-sm whitespace-pre-wrap break-words">{message.content}</p>

                        <div className={`flex items-center justify-between mt-2 ${
                          message.sender_id === currentUser.id ? 'text-white/80' : 'text-gray-500'
                        }`}>
                          <span className="text-xs">{formatTime(message.created_at)}</span>

                          {message.sender_id === currentUser.id && (
                            <div className="flex items-center space-x-1 ml-2">
                              {message.status === 'error' ? (
                                <AlertCircle className="h-3 w-3 text-red-300" />
                              ) : message.status === 'sending' ? (
                                <Clock className="h-3 w-3 opacity-70 animate-pulse" />
                              ) : message.is_read ? (
                                <CheckCheck className="h-3 w-3 text-blue-300" />
                              ) : (
                                <Check className="h-3 w-3 opacity-70" />
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ))
            )}

            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white dark:bg-neutral-800 rounded-2xl rounded-bl-none p-3 border border-neutral-200 dark:border-neutral-700">
                  <div className="flex items-center space-x-2">
                    <div className="flex space-x-1">
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce"></div>
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                    </div>
                    <span className="text-xs text-gray-500">
                      {adminInfo?.first_name || 'Conseiller'} écrit...
                    </span>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Zone de saisie */}
      <div className="p-3 border-t dark:border-neutral-800 bg-white dark:bg-neutral-900 rounded-b-2xl">
        {error ? (
          <div className="text-center p-3">
            <p className="text-sm text-red-600 dark:text-red-400 mb-2">{error}</p>
            <button
              onClick={handleRetry}
              className="text-sm text-primary-600 dark:text-primary-400 hover:underline"
            >
              Réessayer la connexion
            </button>
          </div>
        ) : (
          <>
            <div className="flex items-center space-x-2">
              <div className="flex-1 relative">
                <input
                  ref={chatInputRef}
                  type="text"
                  value={inputMessage}
                  onChange={(e) => {
                    setInputMessage(e.target.value);
                    if (e.target.value.trim()) {
                      handleTyping();
                    }
                  }}
                  onKeyPress={handleKeyPress}
                  placeholder="Écrivez votre message..."
                  className="w-full pl-4 pr-12 py-3 rounded-xl border dark:border-neutral-700 bg-white dark:bg-neutral-800 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all"
                  disabled={isLoading || !!error}
                />
                <div className="absolute right-3 top-1/2 transform -translate-y-1/2 flex items-center space-x-2">
                  <button className="p-1 hover:bg-gray-100 dark:hover:bg-neutral-700 rounded">
                    <Smile className="h-4 w-4 text-gray-500" />
                  </button>
                  <button className="p-1 hover:bg-gray-100 dark:hover:bg-neutral-700 rounded">
                    <Paperclip className="h-4 w-4 text-gray-500" />
                  </button>
                </div>
              </div>
              <button
                onClick={handleSendMessage}
                disabled={!inputMessage.trim() || isLoading || !!error}
                className="p-3 rounded-xl bg-primary-500 text-white hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex-shrink-0"
              >
                <Send className="h-5 w-5" />
              </button>
            </div>
            <div className="mt-2 text-xs text-gray-500 text-center flex items-center justify-center">
              <Clock className="h-3 w-3 mr-1" />
              {adminInfo?.status === 'online' 
                ? 'Temps de réponse moyen : 2-5 minutes' 
                : 'L\'administrateur est actuellement hors ligne'}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default ChatModal;
